const bells = new Audio('data:audio/mpeg;base64,');
bells.loop=true;
const musicButton=document.getElementById('music');
function showMusic(){musicButton.textContent=bells.paused?'♫ 音乐关':'♫ 音乐开';musicButton.setAttribute('aria-pressed',String(!bells.paused));}
musicButton.onclick=async function(){
  if(!bells.paused) bells.pause();
  else try { await bells.play(); } catch(e){musicButton.textContent='音乐暂不可用';}
};
bells.onplay=showMusic;bells.onpause=showMusic;
document.addEventListener('visibilitychange',()=>{if(document.hidden) bells.pause();});
